def trend_report(values_by_group):
    """Smooth each group's series, then average the smoothed values."""
    if not values_by_group:
        return []

    smoothed_groups = {}
    for region, values in values_by_group.items():
        if not values:
            continue
        smoothed = simple_moving_average(values, window=3)
        smoothed_groups[region] = smoothed

    # Calculate average of smoothed values for each region
    final_report = []
    for region, smoothed in smoothed_groups.items():
        avg_smoothed = sum(smoothed) / len(smoothed) if smoothed else 0.0
        final_report.append({
            "region": region,
            "trend": round(avg_smoothed, 3)
        })

    return sorted(final_report, key=lambda x: x["region"])


